/**
 * E2E suite — runs inside the VSCode extension host (SPEC.md §5).
 *
 * ESM test-runner contract (VSCode ≥ 1.90, `extHostExtensionService
 * #_doHandleExtensionTests`): the module must export
 *   run(testsPath): Promise<void>
 * — the host passes this file's own path and settles the run from the
 * returned Promise (resolves → success, rejects → failure). A second,
 * optional `onComplete(error?, failures?)` callback is passed as well;
 * this suite uses the documented Promise channel only.
 *
 * Workspace: `test/integration/workspace/` (generated by the runner) —
 * the reference mini-project (test/fixtures/*) + e2e-only cases in e2e/.
 *
 * Reference invariants (locked by the unit suite — 156 tests):
 *   5 features / 12 steps · 3 PHP / 9 definitions · 11 matching pairs
 *   · undefined step: commandes.feature line 12 (1-based)
 *   · orphan definition: CommandeSteps.php line 31 (1-based)
 *   · 0 duplicates.
 */
import * as vscode from "vscode";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { access, unlink, writeFile } from "node:fs/promises";
import { join } from "node:path";

// --- mini test framework (dependency-free, registry + run Promise) -------

const tests = [];
function test(name, fn) {
  tests.push({ name, fn });
}

// --- helpers ---------------------------------------------------------------

function workspaceRoot() {
  const roots = vscode.workspace.workspaceFolders;
  assert.ok(roots && roots.length > 0, "a workspace folder is open");
  return roots[0].uri;
}

function docUri(relPath) {
  return vscode.Uri.joinPath(workspaceRoot(), relPath);
}

/**
 * The test host starts running before `onStartupFinished` fires, so the
 * extension (activated on startup) may not be active yet — poll until it
 * is. Product activation policy stays `onStartupFinished` (the index glob
 * is user-configurable, so a lazy `workspaceContains` event could miss it).
 */
async function waitForActivation(timeoutMs = 20000) {
  const ext = vscode.extensions.getExtension("ailonn.gherkin-behat-linker");
  assert.ok(ext, "the development extension is installed");
  const start = Date.now();
  while (!ext.isActive) {
    if (Date.now() - start > timeoutMs) {
      throw new Error(`extension not activated after ${timeoutMs} ms`);
    }
    await new Promise((resolve) => setTimeout(resolve, 100));
  }
}

/** Poll an (async) predicate until truthy — the index builds async. */
async function waitFor(label, predicate, timeoutMs = 15000) {
  const start = Date.now();
  for (;;) {
    if (await predicate()) {
      return;
    }
    if (Date.now() - start > timeoutMs) {
      throw new Error(`timeout waiting for: ${label}`);
    }
    await new Promise((resolve) => setTimeout(resolve, 100));
  }
}

/** Location | Location[] | LocationLink[] → normalized {uri, range}[]. */
function toLocations(result) {
  const arr = Array.isArray(result) ? result : result ? [result] : [];
  return arr.map((l) => ({
    uri: l.targetUri ?? l.uri,
    range: l.targetRange ?? l.range,
  }));
}

/** Hover | Hover[] | undefined → concatenated plain text. */
function hoverText(hovers) {
  const arr = Array.isArray(hovers) ? hovers : hovers ? [hovers] : [];
  return arr
    .flatMap((h) => (Array.isArray(h.contents) ? h.contents : [h.contents]))
    .map((c) => (typeof c === "string" ? c : c.value ?? String(c)))
    .join("\n");
}

const ERROR = vscode.DiagnosticSeverity.Error;
const WARNING = vscode.DiagnosticSeverity.Warning;
const INFO = vscode.DiagnosticSeverity.Information;

/**
 * The squiggle spans the whole flagged line (day-1 signal): the range
 * starts at column 0 and ends at the actual line length of the source.
 */
function assertFullLineRange(root, relPath, d) {
  const line =
    readFileSync(join(root, relPath), "utf8")
      .split(/\r?\n/)[d.range.start.line] ?? "";
  // vscode.Position exposes `character` (not LSP's `column`).
  assert.equal(d.range.start.character, 0, "range starts at column 0");
  assert.equal(d.range.end.line, d.range.start.line, "range stays on the flagged line");
  assert.equal(d.range.end.character, line.length, "range ends at the line length");
}

// --- E1 smoke (harness proof, not an AC) ----------------------------------

test("E1: e2e workspace is open (reference fixtures + e2e cases)", async () => {
  const root = workspaceRoot().fsPath;
  assert.match(root, /workspace/, "the generated workspace is the folder");
  assert.equal(
    await access(join(root, "commandes.feature")).then(
      () => true,
      () => false
    ),
    true,
    "reference fixture copied"
  );
  assert.equal(
    await access(join(root, "e2e", "broken.feature")).then(
      () => true,
      () => false
    ),
    true,
    "e2e-only fixture copied"
  );
});

test("E1: extension activates and the command bus works (ESM main)", async () => {
  await waitForActivation();
  const pong = await vscode.commands.executeCommand("gherkinBehat.ping");
  assert.equal(pong, "pong", "gherkinBehat.ping resolves to 'pong'");
});

// --- AC-1: feature → definition (SPEC §3) ----------------------------------

test("AC-1: feature step → PHP definition (type-agnostic, static, no vendor/)", async () => {
  await waitForActivation();
  // AC-5 (static): the workspace carries no PHP runtime at all.
  const root = workspaceRoot().fsPath;
  assert.equal(
    await access(join(root, "vendor")).then(() => true, () => false),
    false,
    "the e2e workspace has no vendor/ (AC-5)"
  );
  const doc = await vscode.workspace.openTextDocument(docUri("commandes.feature"));
  // line 6 (1-based): Quand je valide la commande "CMD-2026" avec succès
  // → @When /je valide la commande "(?P<numero>[\w.-]+)"/ — CommandeSteps.php
  //   line 15 (1-based) = line 14 (0-based).
  const pos = new vscode.Position(5, 10);
  await waitFor("AC-1: definition of the step at line 6", async () => {
    const res = await vscode.commands.executeCommand(
      "vscode.executeDefinitionProvider",
      doc.uri,
      pos
    );
    return toLocations(res).some(
      (l) => l.uri.fsPath.endsWith("CommandeSteps.php") && l.range.start.line === 14
    );
  });
});

// --- AC-2: definition → usages (reverse) -----------------------------------

test("AC-2: PHP definition → all matching feature steps (reverse)", async () => {
  await waitForActivation();
  const php = await vscode.workspace.openTextDocument(docUri("CommandeSteps.php"));
  // the @When annotation, line 15 (1-based) = line 14 (0-based)
  const pos = new vscode.Position(14, 10);
  await waitFor("AC-2: usages of the @When definition", async () => {
    const res = await vscode.commands.executeCommand(
      "vscode.executeReferenceProvider",
      php.uri,
      pos
    );
    return toLocations(res).some(
      (l) => l.uri.fsPath.endsWith("commandes.feature") && l.range.start.line === 5
    );
  });
});

// --- AC-3: diagnostics (SPEC §3) --------------------------------------------

test("AC-3: undefined step → error diagnostic (commandes.feature line 12)", async () => {
  await waitForActivation();
  const doc = await vscode.workspace.openTextDocument(docUri("commandes.feature"));
  await waitFor("AC-3: error diagnostic on commandes.feature", async () => {
    return vscode.languages
      .getDiagnostics(doc.uri)
      .some((d) => d.severity === ERROR);
  });
  const errors = vscode.languages
    .getDiagnostics(doc.uri)
    .filter((d) => d.severity === ERROR);
  assert.equal(errors.length, 1, "exactly one undefined step in the reference");
  assert.equal(errors[0].range.start.line, 11, "line 12 (1-based) = 11 (0-based)");
  assert.match(errors[0].message, /undefined/i, "message says the step is undefined");
  assertFullLineRange(workspaceRoot().fsPath, "commandes.feature", errors[0]);
});

test("AC-3: orphan definition → info diagnostic (CommandeSteps.php line 31)", async () => {
  await waitForActivation();
  const php = await vscode.workspace.openTextDocument(docUri("CommandeSteps.php"));
  await waitFor("AC-3: info diagnostic on CommandeSteps.php", async () => {
    return vscode.languages
      .getDiagnostics(php.uri)
      .some((d) => d.severity === INFO);
  });
  const infos = vscode.languages
    .getDiagnostics(php.uri)
    .filter((d) => d.severity === INFO);
  const orphan = infos.find(
    (d) => d.range.start.line === 30 && /orphan/i.test(d.message)
  );
  assert.ok(
    orphan,
    `orphan info at line 30 (0-based): ${JSON.stringify(
      infos.map((d) => [d.range.start.line, d.message])
    )}`
  );
  assertFullLineRange(workspaceRoot().fsPath, "CommandeSteps.php", orphan);
  // no duplicate warnings anywhere in the reference PHP files (0 duplicates)
  for (const f of ["CommandeSteps.php", "OrderSteps.php", "BestellungSteps.php"]) {
    const d = await vscode.workspace.openTextDocument(docUri(f));
    const warnings = vscode.languages
      .getDiagnostics(d.uri)
      .filter((x) => x.severity === WARNING);
    assert.equal(warnings.length, 0, `no warnings in ${f}`);
  }
});

test("AC-3: duplicate definitions → warning diagnostics (e2e fixture)", async () => {
  await waitForActivation();
  const dup = await vscode.workspace.openTextDocument(docUri("e2e/DoublonSteps.php"));
  await waitFor("AC-3: warning diagnostics on DoublonSteps.php", async () => {
    return vscode.languages
      .getDiagnostics(dup.uri)
      .filter((d) => d.severity === WARNING).length === 2;
  });
  const warnings = vscode.languages
    .getDiagnostics(dup.uri)
    .filter((d) => d.severity === WARNING);
  const lines = warnings.map((d) => d.range.start.line).sort((a, b) => a - b);
  assert.deepEqual(lines, [7, 14], "both annotation lines flagged (0-based)");
  for (const d of warnings) {
    assert.match(d.message, /duplicate/i, "message says the definition is duplicated");
    assertFullLineRange(workspaceRoot().fsPath, "e2e/DoublonSteps.php", d);
  }
});

test("AC-3: untranslatable expression → info diagnostic WITH the reason (e2e fixture)", async () => {
  await waitForActivation();
  const doc = await vscode.workspace.openTextDocument(
    docUri("e2e/UntranslatableSteps.php")
  );
  await waitFor("AC-3: untranslatable info diagnostic", async () => {
    return vscode.languages
      .getDiagnostics(doc.uri)
      .some((d) => d.severity === INFO && /\\K|not supported/i.test(d.message));
  });
  const diag = vscode.languages
    .getDiagnostics(doc.uri)
    .filter((d) => d.severity === INFO && /\\K|not supported/i.test(d.message));
  assert.ok(diag.length >= 1, "the untranslatable diagnostic exists");
  assert.equal(diag[0].range.start.line, 7, "annotation line 8 (1-based) = 7 (0-based)");
  assertFullLineRange(workspaceRoot().fsPath, "e2e/UntranslatableSteps.php", diag[0]);
});

test("AC-3: unparseable Gherkin → error diagnostic (e2e fixture)", async () => {
  await waitForActivation();
  const doc = await vscode.workspace.openTextDocument(docUri("e2e/broken.feature"));
  await waitFor("AC-3: error diagnostic on broken.feature", async () => {
    return vscode.languages
      .getDiagnostics(doc.uri)
      .some((d) => d.severity === ERROR);
  });
  const errors = vscode.languages
    .getDiagnostics(doc.uri)
    .filter((d) => d.severity === ERROR);
  assert.equal(errors.length, 1, "one error for the unparseable file");
  assert.equal(
    errors[0].range.start.line,
    4,
    "the parser-reported line (5: in the reason) = 4 (0-based)"
  );
  assertFullLineRange(workspaceRoot().fsPath, "e2e/broken.feature", errors[0]);
});

// --- AC-4: hover (both directions) ------------------------------------------

test("AC-4: hover on a step → FQCN, method, expression (with named groups)", async () => {
  await waitForActivation();
  const doc = await vscode.workspace.openTextDocument(docUri("commandes.feature"));
  const pos = new vscode.Position(5, 10); // line 6 (1-based)
  let text = "";
  await waitFor("AC-4: step hover carries the definition details", async () => {
    const hovers = await vscode.commands.executeCommand(
      "vscode.executeHoverProvider",
      doc.uri,
      pos
    );
    text = hoverText(hovers);
    return text.includes("App\\Behat\\CommandeSteps");
  });
  // The executeHoverProvider round trip serializes the markdown
  // (`*` → `\*`, spaces → `&nbsp;`) — normalize back to the raw value
  // before asserting on the contract (code blocks pass through untouched).
  const plain = text.replace(/&nbsp;/g, " ").replace(/\\\*/g, "*");
  assert.ok(text.includes("laCommandeValidee"), "method name in the hover");
  assert.ok(text.includes("numero"), "named group ↔ parameter shown");
  assert.ok(
    plain.includes("step keyword:* Quand"),
    "the step keyword as display metadata (hover.feature)"
  );
  assert.ok(
    !plain.includes("string $"),
    "no fabricated parameter types — the scanner drops them by design"
  );
});

test("AC-4: hover on a definition → its usages", async () => {
  await waitForActivation();
  const php = await vscode.workspace.openTextDocument(docUri("CommandeSteps.php"));
  const pos = new vscode.Position(14, 10); // @When, line 15 (1-based)
  let text = "";
  await waitFor("AC-4: definition hover carries the usages", async () => {
    const hovers = await vscode.commands.executeCommand(
      "vscode.executeHoverProvider",
      php.uri,
      pos
    );
    text = hoverText(hovers);
    return text.includes("commandes.feature");
  });
  assert.ok(
    text.includes("je valide la commande"),
    "the matching step text in the hover"
  );
});

test("AC-4: hover on an untranslatable definition → the reason (fail loud)", async () => {
  await waitForActivation();
  const doc = await vscode.workspace.openTextDocument(
    docUri("e2e/UntranslatableSteps.php")
  );
  const pos = new vscode.Position(7, 10); // annotation, line 8 (1-based)
  let text = "";
  await waitFor("AC-4: untranslatable hover carries the reason", async () => {
    const hovers = await vscode.commands.executeCommand(
      "vscode.executeHoverProvider",
      doc.uri,
      pos
    );
    text = hoverText(hovers);
    return /\\K|not supported/i.test(text);
  });
});

// --- AC-5: static rebuild (watcher → debounce → re-index) --------------------

test("AC-5: rebuild — a new feature file is indexed by the watcher", async () => {
  await waitForActivation();
  const file = join(workspaceRoot().fsPath, "rebuild_scratch.feature");
  await writeFile(
    file,
    "Feature: Rebuild\n\n  Scenario: Scratch\n    Given a step that exists nowhere\n",
    "utf8"
  );
  try {
    await waitFor(
      "AC-5: undefined-step diagnostic on the new file",
      async () => {
        const doc = await vscode.workspace.openTextDocument(vscode.Uri.file(file));
        return vscode.languages
          .getDiagnostics(doc.uri)
          .some((d) => d.severity === ERROR);
      },
      30000 // watcher + debounce + rebuild budget
    );
  } finally {
    await unlink(file).catch(() => {});
  }
});

// --- entry point (called by the extension host) ------------------------------

/**
 * @param {string} testsPath — this module's file path (passed by the host).
 * @param {(error?: Error, failures?: number) => void} [_onComplete] —
 *   optional host callback; unused (Promise channel only).
 */
export function run(testsPath, _onComplete) {
  void _onComplete;
  void testsPath;
  return (async () => {
    let failures = 0;
    for (const { name, fn } of tests) {
      try {
        await fn();
        console.log(`ok - ${name}`);
      } catch (err) {
        failures += 1;
        console.error(`FAIL - ${name}`);
        console.error(err);
      }
    }
    console.log(`E2E suite: ${tests.length - failures}/${tests.length} passed`);
    if (failures > 0) {
      throw new Error(`${failures}/${tests.length} e2e test(s) failed`);
    }
  })();
}
